package pzvrphysicality;
import java.nio.file.*;import java.util.*;import java.util.jar.*;
import net.bytebuddy.ByteBuddy;import net.bytebuddy.asm.Advice;import net.bytebuddy.dynamic.ClassFileLocator;import net.bytebuddy.pool.TypePool;import net.bytebuddy.jar.asm.*;
import static net.bytebuddy.matcher.ElementMatchers.named;
/** Read and compose copied SDK bytecode only. No original class is loaded or invoked. */
public final class NativeInputCompositionTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 private static Map<String,List<String>> methods(byte[] bytes){var result=new LinkedHashMap<String,List<String>>();new ClassReader(bytes).accept(new ClassVisitor(Opcodes.ASM9){public MethodVisitor visitMethod(int access,String name,String descriptor,String signature,String[] exceptions){var events=new ArrayList<String>();result.put(name+descriptor,events);return new MethodVisitor(Opcodes.ASM9){public void visitMethodInsn(int op,String owner,String name,String desc,boolean itf){events.add("call:"+owner+"."+name+desc);}public void visitFieldInsn(int op,String owner,String name,String desc){events.add("field:"+op+":"+owner+"."+name+desc);}public void visitLdcInsn(Object value){if(value instanceof String text)events.add("text:"+text);}};}},0);return result;}
 private static long count(List<String> events,String prefix){return events.stream().filter(e->e.startsWith(prefix)).count();}
 private static int at(List<String> events,String prefix){for(int n=0;n<events.size();n++)if(events.get(n).startsWith(prefix))return n;return -1;}
 private static Map<String,Long> nativeCalls(List<String> events){var result=new TreeMap<String,Long>();for(String event:events)if(event.startsWith("call:")&&!event.startsWith("call:pzvrphysicality/"))result.merge(event,1L,Long::sum);return result;}
 private static byte[] advice(Path classes,String name)throws Exception{var reader=new ClassReader(Files.readAllBytes(classes.resolve("pzvrphysicality/"+name+".class")));var writer=new ClassWriter(0);var names=Map.of("OnEnter","OnMethodEnter","OnExit","OnMethodExit","This","This","Argument","Argument","Return","Return","Thrown","Thrown");reader.accept(new ClassVisitor(Opcodes.ASM9,writer){String convert(String descriptor){String prefix="Lme/zed_0xff/zombie_buddy/Patch$";if(!descriptor.startsWith(prefix))return descriptor;var key=descriptor.substring(prefix.length(),descriptor.length()-1);if(!names.containsKey(key))throw new AssertionError(key);return "Lnet/bytebuddy/asm/Advice$"+names.get(key)+";";}public MethodVisitor visitMethod(int access,String name,String descriptor,String signature,String[] exceptions){return new MethodVisitor(Opcodes.ASM9,super.visitMethod(access,name,descriptor,signature,exceptions)){public AnnotationVisitor visitAnnotation(String desc,boolean visible){return new AnnotationVisitor(Opcodes.ASM9,super.visitAnnotation(convert(desc),visible)){public void visit(String key,Object value){if(desc.equals("Lme/zed_0xff/zombie_buddy/Patch$OnEnter;")&&key.equals("skipOn")&&value instanceof Boolean flag){if(flag)super.visit(key,Type.getType("Lnet/bytebuddy/asm/Advice$OnNonDefaultValue;"));return;}super.visit(key,value);}};}public AnnotationVisitor visitParameterAnnotation(int index,String desc,boolean visible){return super.visitParameterAnnotation(index,convert(desc),visible);}};}},0);return writer.toByteArray();}
 private static void compose(ClassFileLocator dependencies,Path classes,Path out,String target,String method,String descriptor,String patch,String callback)throws Exception{
  byte[] original=dependencies.locate(target).resolve(),annotation=advice(classes,patch);var originalEvents=methods(original);check(originalEvents.containsKey(method+descriptor),patch+" exact latest descriptor");check(originalEvents.keySet().stream().filter(k->k.startsWith(method+"(")).count()==1,patch+" strict target has one overload");
  var locator=new ClassFileLocator.Compound(new ClassFileLocator.Simple(Map.of(target,original,"pzvrphysicality."+patch,annotation)),dependencies);var pool=TypePool.Default.of(locator);byte[] rewritten=new ByteBuddy().redefine(pool.describe(target).resolve(),locator).visit(Advice.to(pool.describe("pzvrphysicality."+patch).resolve(),locator).on(named(method))).make().getBytes();var events=methods(rewritten).get(method+descriptor);check(count(events,"call:pzvrphysicality/"+callback)>0,patch+" inserts owned callback");
  check(nativeCalls(events).equals(nativeCalls(originalEvents.get(method+descriptor))),patch+" retains exact native invocation counts");
  Files.write(out.resolve(patch+"-copied.class"),rewritten);
 }
 public static void main(String[] args)throws Exception{
  Path pzvr=Path.of(args[0]),game=Path.of(args[1]),viewpoint=Path.of(args[2]),buddy=Path.of(args[3]),classes=Path.of(args[4]),out=Path.of(args[5]),dependencies=Path.of(args[6]);Files.createDirectories(out);
  try(var locator=new ClassFileLocator.Compound(ClassFileLocator.ForJarFile.of(pzvr.toFile()),ClassFileLocator.ForJarFile.of(game.toFile()),ClassFileLocator.ForJarFile.of(viewpoint.toFile()),ClassFileLocator.ForJarFile.of(buddy.toFile()),new ClassFileLocator.ForFolder(classes.toFile()),new ClassFileLocator.ForFolder(dependencies.toFile()),ClassFileLocator.ForClassLoader.ofPlatformLoader())){
   var engine=methods(locator.locate("local.pzvr.Engine").resolve());String update="(Llocal/pzvr/XrBackend$Frame;Llocal/pzvr/Settings;Z)V";int publications=0;for(var entry:engine.entrySet()){var events=entry.getValue();int publish=at(events,"field:179:local/pzvr/Engine.latestInput"),call=at(events,"call:local/pzvr/InputBridge.update"+update);if(call>=0){publications++;check(publish>=0&&publish<call,"current raw input published before native input/binding routing");}}check(publications==1,"one native frame publication/update path");
   var input=methods(locator.locate("local.pzvr.InputBridge").resolve()).get("update"+update);check(input!=null,"native update is exact three-argument ABI");int filter=at(input,"call:local/pzvr/PhysicalBandaging.filter");check(filter==0,"native bandage filter runs before native binding/grip routing");int grip=at(input,"text:dominant.grip"),binding=at(input.subList(grip,input.size()),"call:local/pzvr/Bindings.resolve")+grip;int consumed=at(input,"call:local/pzvr/GrabSystem.consumed");int request=at(input.subList(consumed,input.size()),"call:local/pzvr/VrControls.request")+consumed;check(grip>=0&&binding>grip&&consumed>binding&&request>consumed,"binding interception and native consumed check precede original grip forwarding");check(at(input,"call:local/pzvr/VehicleSteering.input")<grip,"native grab sampler bridge runs before grip binding interception");check(count(input,"call:local/pzvr/Bindings.handIndex")>0,"native update computes binding sides from native mirror resolver");
   var bindingEvents=methods(locator.locate("local.pzvr.Bindings").resolve()).get("handIndex(Llocal/pzvr/Settings;Z)I");check(count(bindingEvents,"field:180:local/pzvr/Settings.mirrorControllerBindingsZ")==1,"binding resolver reads actual mirror setting");check(count(bindingEvents,"field:180:local/pzvr/Settings.dominantHand")==0,"aim preference does not remap logical bindings");
   var rig=methods(locator.locate("local.pzvr.NativeRig").resolve());var grabPass=rig.values().stream().filter(e->count(e,"call:local/pzvr/GrabSystem.pose")>0).toList();check(grabPass.size()==1,"one native rig physical-side grabbed pose pass");var grabbed=grabPass.get(0);check(count(grabbed,"call:local/pzvr/GrabSystem.pose")==1,"native rig resolves physical-side grabbed pose in its loop");check(count(grabbed,"call:local/pzvr/GrabSystem.grabbed")>0,"native arm receives grabbed-hand priority");check(count(grabbed,"call:local/pzvr/XrBackend$Frame.left")>0&&count(grabbed,"call:local/pzvr/XrBackend$Frame.right")>0,"native rig retains physical left/right frame mapping");
   compose(locator,classes,out,"local.pzvr.InputBridge","update",update,"NativeInputOwnershipAdvice","NativeInputOwnership.observe");
   compose(locator,classes,out,"local.pzvr.NativeRig","capture","(Ljava/lang/Object;Lzombie/core/skinnedmodel/model/ModelSlotRenderData;Lzombie/characters/IsoGameCharacter;)V","FingerCaptureAdvice","FingerPoseDriver.begin");
   compose(locator,classes,out,"local.pzvr.NativeRig","posture","(Lzombie/core/skinnedmodel/model/SkinningData;[Lorg/joml/Matrix4f;[Lorg/joml/Matrix4f;Lorg/joml/Matrix4f;Lorg/joml/Matrix4f;Llocal/pzvr/Math3$Vec;Llocal/pzvr/XrBackend$Frame;Llocal/pzvr/Math3$Pose;)[Lorg/joml/Matrix4f;","FingerFrameAdvice","FingerPoseDriver.frame");
   compose(locator,classes,out,"local.pzvr.NativeRig","fingers","(Lzombie/core/skinnedmodel/model/SkinningData;[Lorg/joml/Matrix4f;[Lorg/joml/Matrix4f;IF[Lorg/joml/Matrix4f;)V","FingerPoseAdvice","FingerPoseDriver.pose");
   compose(locator,classes,out,"local.pzvr.OpenXrBackend","suggest","(Llocal/pzvr/ControllerProfiles$Profile;Lorg/lwjgl/system/MemoryStack;)V","ControllerTouchSuggestAdvice","ControllerTouch.suggest");
   compose(locator,classes,out,"local.pzvr.OpenXrBackend","createActions","(Lorg/lwjgl/system/MemoryStack;)V","ControllerTouchAttachAdvice","ControllerTouch.actionsCreated");
   compose(locator,classes,out,"local.pzvr.OpenXrBackend","readHands","(Lorg/lwjgl/system/MemoryStack;J)[Llocal/pzvr/XrBackend$Hand;","ControllerTouchReadAdvice","ControllerTouch.capture");
   compose(locator,classes,out,"local.pzvr.OpenXrBackend","close","()V","ControllerTouchCloseAdvice","ControllerTouch.close");
  }
  var callers=new ArrayList<String>();try(var jar=new JarFile(pzvr.toFile())){for(var entry:Collections.list(jar.entries()))if(entry.getName().startsWith("local/pzvr/")&&entry.getName().endsWith(".class")){try(var stream=jar.getInputStream(entry)){for(var method:methods(stream.readAllBytes()).entrySet())if(count(method.getValue(),"call:local/pzvr/GrabSystem.sample")>0)callers.add(entry.getName()+":"+method.getKey());}}}check(callers.equals(List.of("local/pzvr/VehicleSteering.class:input(Llocal/pzvr/XrBackend$Frame;Llocal/pzvr/Settings;II)V")),"native grab sample caller matches pre-binding vehicle input bridge");Files.writeString(out.resolve("grab-sample-callers.txt"),String.join("\n",callers));
  System.out.println("Native input composition: "+checks+" checks passed; copied SDK bytecode only; original methods unexecuted");
 }
 private NativeInputCompositionTest(){}
}
